<?php $s=$analytics['summary']; $risk=$analytics['risk']; $sys=$analytics['by_system']; $ses=$analytics['by_session']; $expectedR=null;$ev=[];foreach($analytics['trades'] as $t){if($t['risk']['expected_r']!==null)$ev[]=(float)$t['risk']['expected_r'];}if($ev)$expectedR=array_sum($ev)/count($ev);$monthly=[];foreach($analytics['trades'] as $t){$m=date('Y-m',strtotime((string)$t['closed_at']));$monthly[$m]=($monthly[$m]??0)+(float)$t['pnl'];} ?>
<div class="page-title">Advanced Analytics</div><p class="page-subtitle">Performance analysis across systems, sessions, timeframes and risk management</p>
<form method="get" class="card" style="padding:10px"><div class="grid"><p><label>Trading system</label><select name="system_id"><option value="">All systems</option><?php foreach($systems as $x):?><option value="<?=e($x['id'])?>" <?=((int)($filters['system_id']??0)===(int)$x['id'])?'selected':''?>><?=e($x['name'])?></option><?php endforeach;?></select></p><p><label>Session</label><select name="session_id"><option value="">All sessions</option><?php foreach($sessions as $x):?><option value="<?=e($x['id'])?>" <?=((int)($filters['session_id']??0)===(int)$x['id'])?'selected':''?>><?=e($x['name'])?></option><?php endforeach;?></select></p><p><label>From</label><input type="date" name="date_from" value="<?=e($filters['date_from']??'')?>"></p><p><label>To</label><input type="date" name="date_to" value="<?=e($filters['date_to']??'')?>"></p></div><button>Apply filters</button></form>
<div class="stats-grid"><div class="metric"><div class="label">Expected Value (EV)</div><div class="value positive"><?= $s['expectancy']===null?'—':number_format($s['expectancy'],2).'R' ?></div><div class="hint">Average expected return per trade</div></div><div class="metric"><div class="label">Win Rate</div><div class="value"><?= $s['win_rate']===null?'—':number_format($s['win_rate'],1).'%' ?></div><div class="hint"><?=number_format($s['wins'])?> wins / <?=number_format($s['count'])?> trades</div></div><div class="metric"><div class="label">Total Expected R</div><div class="value positive"><?= $expectedR===null?'—':number_format($expectedR,2).'R' ?></div><div class="hint">Average normalized return</div></div><div class="metric"><div class="label">Risk Management</div><div class="value warning"><?=number_format($risk['avg_risk_deviation']??0,0)?>%</div><div class="hint">Average risk deviation</div></div></div>
<div class="report-grid"><div class="card chart-card"><h2>System Expected Value Comparison</h2><div class="sub">Expected value by trading system</div><canvas id="sysChart"></canvas></div><div class="card chart-card"><h2>Timeframe Expected Value</h2><div class="sub">Performance by timeframe</div><canvas id="tfChart"></canvas></div><div class="card chart-card"><h2>Session Expected Value</h2><div class="sub">Performance by trading session</div><canvas id="sessionChart"></canvas></div><div class="card chart-card"><h2>Monthly Expected Value Trend</h2><div class="sub">Expected value performance over time</div><canvas id="monthChart"></canvas></div><div class="card"><h2>System Performance Breakdown</h2><div class="sub">Detailed metrics by trading system</div><?php foreach($sys as $g):?><div class="bar-row"><span><?=e($g['name'])?></span><div class="bar-track"><div class="bar-fill" style="width:<?=min(100,abs((float)$g['net_pnl']))?>%"></div></div><strong class="<?=((float)$g['net_pnl']>=0?'positive':'negative')?>"><?=number_format($g['net_pnl'],2)?></strong></div><?php endforeach;if(!$sys):?><p class="muted">No system data yet.</p><?php endif;?></div><div class="card"><h2>Risk Management Analysis</h2><div class="sub">Risk execution breakdown</div><div class="mini-grid"><div class="mini-stat"><strong class="positive"><?=number_format($risk['risk_tracked_trades']-$risk['over_risk_trades'])?></strong><span class="muted">Good Risk</span></div><div class="mini-stat"><strong class="negative"><?=number_format($risk['over_risk_trades'])?></strong><span class="muted">Over-Risked</span></div><div class="mini-stat"><strong class="warning"><?=number_format(max(0,$s['count']-$risk['risk_tracked_trades']))?></strong><span class="muted">Under/Untracked</span></div></div></div></div>
<script src="https://cdn.jsdelivr.net/npm/chart.js"></script><script nonce="<?=e(csp_nonce())?>">const o={responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{x:{ticks:{font:{size:8}}},y:{ticks:{font:{size:8}}}}};function mk(id,type,labels,data){new Chart(document.getElementById(id),{type,data:{labels,datasets:[{data,borderColor:'#ec6a4f',backgroundColor:'rgba(236,106,79,.78)',borderWidth:1.5,pointRadius:2,tension:.25}]},options:o})}const tf=<?=json_encode(array_reduce($analytics['trades'],function($a,$t){$k=$t['timeframe']??'Unknown';$a[$k]=($a[$k]??0)+($t['pnl']??0);return $a;},[]))?>;mk('sysChart','bar',<?=json_encode(array_column($sys,'name'))?>,<?=json_encode(array_map(fn($x)=>$x['avg_r']??0,$sys))?>);mk('tfChart','bar',Object.keys(tf),Object.values(tf));mk('sessionChart','bar',<?=json_encode(array_column($ses,'name'))?>,<?=json_encode(array_map(fn($x)=>$x['avg_r']??0,$ses))?>);mk('monthChart','line',<?=json_encode(array_keys($monthly))?>,<?=json_encode(array_values($monthly))?>);</script>
